{"path": "unique.mjs", "content": "export function uniqueBy(items, key = "id") {
  const seen = new Set();
  return items.filter((item) => {
    const value = item[key];
    if (seen.has(value)) return false;
    seen.add(value);
    return true;
  });
}
"}

